SELECT "nct", "author", "year", "pubmed_id", "trial_name", "trial_phase", "cancer_type", "treatment_regimen", "control_regimen", "class_of_ici", "name_of_ici", "type_of_combination", "type_of_control" FROM public."clinical_trials" WHERE "trial_phase" = 'Phase 3' AND "cancer_type" = 'Non-Small Cell Lung' AND "class_of_ici" = 'PD1' AND "name_of_ici" ILIKE '%PDL1%' AND "type_of_combination" = 'Combination' AND "class_of_ici_1" = 'CTLA4' AND "name_of_ici_1" ILIKE '%CTLA4%'